uint64_t GetElapsedTime()
{
	static struct timeval tv;
	static struct tm stm;
	static uint64_t uiPrevTime;
	static uint64_t uiCurrTime;
	gettimeofday(&tv,NULL);
	localtime_r(&tv.tv_sec,&stm);
	uiPrevTime = uiCurrTime;
	uiCurrTime = stm.tm_hour * 3600000 + stm.tm_min * 60000 + stm.tm_sec * 1000 + tv.tv_usec / 1000;
	return uiCurrTime - uiPrevTime;
}



