int32_t SetSerialNo(uint32_t num, int32_t val) 
{ 
	if(num >= 25)
		return -1; 

	g_SerNo[num] = val; 
	return 0; 
}; 

int32_t GetSerialNo(uint32_t num) 
{ 
	if(num >= 25)
		return -1; 
	return __sync_add_and_fetch(&g_SerNo[num], 1); 
} 

SERIAL_NO *GetSerialNoFunc() 
{ 
	static SERIAL_NO lpSerialNo[] = 
	{ 
		{GetSerialNo, SetSerialNo}, 
		{NULL, NULL} 
	}; 
	return lpSerialNo; 
} 

